Filtering and searching through `rightsNodes` and `visualReceiptNodes` inside loops leads to O(N * M) complexity. Mapping these lookup keys to a Map beforehand reduces the complexity to O(N + M), preserving the existing classification behavior while significantly improving performance.

```javascript
  const questionNodes = nodes.filter((row) => toStringValue(row.node_family, row.nodeFamily, null) === 'Question');
  const methodMapNodes = nodes.filter((row) => row.node_family === 'MethodMap');
  const figureAssetNodes = nodes.filter((row) => toStringValue(row.node_family, null, null) === 'SourceFigureAsset');
  const visualReceiptNodes = nodes.filter((row) => toStringValue(row.node_family, null, null) === 'SourceVisualReceipt');
  const rightsNodes = nodes.filter((row) => toStringValue(row.node_family, null, null) === 'RightsDisplayPolicy');

  const rightsNodesById = new Map();
  for (const rightNode of rightsNodes) {
    const id = toStringValue(rightNode.node_id, rightNode.nodeId, null);
    if (id) {
      rightsNodesById.set(id, rightNode);
    }
  }

  const receiptByQuestionKey = new Map();
  for (const candidate of visualReceiptNodes) {
    const key = candidate?.properties?.question_key;
    if (key) {
      receiptByQuestionKey.set(key, candidate);
    }
    const sourceRefs = toArray(candidate?.source_refs);
    for (const sr of sourceRefs) {
      if (sr?.question_key) {
        receiptByQuestionKey.set(sr.question_key, candidate);
      }
    }
  }
